// @Repository — data access; adds automatic exception translation
@Repository
public class JdbcOrderRepository {
    private final JdbcTemplate jdbc;
    public JdbcOrderRepository(JdbcTemplate jdbc) { this.jdbc = jdbc; }

    public Order findById(Long id) {
        // A raw SQLException is translated into Spring's DataAccessException
        return jdbc.queryForObject(
            "SELECT * FROM orders WHERE id = ?", orderRowMapper(), id);
    }
}

// @Service — business logic; purely semantic, no extra behavior
@Service
public class OrderService {
    private final JdbcOrderRepository repository;
    public OrderService(JdbcOrderRepository repository) { this.repository = repository; }
    public Order getOrder(Long id) { return repository.findById(id); }
}

// @RestController — web layer; @Controller + @ResponseBody with MVC mapping
@RestController
@RequestMapping("/orders")
public class OrderController {
    private final OrderService service;
    public OrderController(OrderService service) { this.service = service; }

    @GetMapping("/{id}")
    public Order get(@PathVariable Long id) { return service.getOrder(id); }
}
